def parse_fail_part(file_name, line):
    """
    解析excel文件
    :param file_name: excel文件名
    """
    df = pd.read_excel(file_name, engine="xlrd")
    # 计算每个'category'的计数
    count_by_category = df["TEST_LINE"].value_counts()
    data = []
    for l, c in zip(count_by_category.index, count_by_category.values):
        if line in l:
            data.append({"line": l, "fail": c.__int__()})
    return data

def test(line):
    """测试:筛选每条线的不良数据
    :param line: 线别
    :return:
    """
    df = pd.read_excel("D:/Program Files (x86)/web/211.xls", engine="xlrd")
    due_fail_groupby=df.groupby(["TEST_LINE",'ERROR_DESC'])["TEST_LINE"].count()
    line_fail_detail=df.loc[df['TEST_LINE']==line].groupby('ERROR_DESC')["TEST_LINE"].count().sort_values(ascending=False)
    for k,v in json.loads(line_fail_detail.to_json()).items():
        print(k,v)


